def group_states(grid, goal):
    rows = len(grid)
    cols = len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]  # right, left, down, up

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != "X"

    def bfs(start):
        queue = [(start, [start])]
        visited = set([start])

        while queue:
            (x, y), path = queue.pop(0)
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    new_path = list(path)
                    if grid[nx][ny] == goal:
                        new_path.append((nx, ny))
                        groups.append(new_path)
                        return
                    else:
                        queue.append(((nx, ny), new_path + [(nx, ny)]))
                        visited.add((nx, ny))

    groups = []
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != "X" and (i, j) not in [tuple(x) for x in groups]:
                bfs((i, j))

    abstract_states = {}
    state_index = 0

    for group in groups:
        for state in group:
            abstract_states[state] = state_index
        state_index += 1

    # Map the states from the original grid to their corresponding abstract state index.
    mapped_grid = []

    for i in range(rows):
        row = []
        for j in range(cols):
            if grid[i][j] != "X":
                row.append(abstract_states[(i, j)])
            else:
                row.append("X")
        mapped_grid.append(row)

    # Group states by their abstract state index
    result = {}

    for i in range(rows):
        for j in range(cols):
            if mapped_grid[i][j] != "X":
                if mapped_grid[i][j] not in result:
                    result[mapped_grid[i][j]] = []
                result[mapped_grid[i][j]].append(grid[i][j])

    return list(result.values())

